            cipher.init(Cipher.ENCRYPT_MODE, secretKeySpec, gcmParameterSpec);

            // Perform encryption
            byte[] encryptedData = cipher.doFinal(data);

            // Combine IV and encrypted data (IV is needed for decryption)
            byte[] combined = new byte[iv.length + encryptedData.length];
            System.arraycopy(iv, 0, combined, 0, iv.length);
            System.arraycopy(encryptedData, 0, combined, iv.length, encryptedData.length);

            // Convert to hexadecimal string and return
            return bytesToHex(combined);

        } catch (IllegalArgumentException e) {
            throw e;
        } catch (Exception e) {
            throw new RuntimeException("AES encryption failed: " + e.getMessage(), e);
        }
    }

    /**
     * Normalizes the key to a valid AES key length (16, 24, or 32 bytes)
     *
     * @param key The original key string
     * @return A byte array of valid AES key length
     */
    private static byte[] normalizeKey(String key) {
        byte[] keyBytes = key.getBytes(java.nio.charset.StandardCharsets.UTF_8);

        // Determine target key length (default to AES-128 if key is short)
        int targetLength;
        if (keyBytes.length >= 32) {
            targetLength = 32; // AES-256
        } else if (keyBytes.length >= 24) {
            targetLength = 24; // AES-192
        } else {
            targetLength = 16; // AES-128
        }

        // Create normalized key array
        byte[] normalizedKey = new byte[targetLength];

        // Copy or pad the key bytes
        if (keyBytes.length >= targetLength) {
            System.arraycopy(keyBytes, 0, normalizedKey, 0, targetLength);
        } else {
            // Pad with zeros if key is too short
            System.arraycopy(keyBytes, 0, normalizedKey, 0, keyBytes.length);
        }

        return normalizedKey;
    }

    /**
     * Generates a cryptographically secure random IV for GCM mode
     *
     * @return A random 12-byte IV
     */
    private static byte[] generateSecureIV() {
        byte[] iv = new byte[GCM_IV_LENGTH];
        SecureRandom secureRandom = new SecureRandom();
        secureRandom.nextBytes(iv);
        return iv;
    }

    /**
     * Converts a byte array to a hexadecimal string
     *
     * @param bytes The byte array to convert
     * @return The hexadecimal string representation
     */
    private static String bytesToHex(byte[] bytes) {
        StringBuilder hexString = new StringBuilder(bytes.length * 2);
        for (byte b : bytes) {
            hexString.append(HEX_CHARS[(b >> 4) & 0x0F]);
            hexString.append(HEX_CHARS[b & 0x0F]);
        }
        return hexString.toString();
    }
}
